extension IslandCharacter {
    var title: String {
        switch self {
        case .dino: "Dino"
        case .ghost: "Ghost"
        case .crab: "Crab"
        case .duck: "Duck"
        case .claude: "Claude"
        case .cat: "Cat"
        case .robot: "Robot"
        case .octopus: "Octopus"
        case .frog: "Frog"
        case .slime: "Slime"
        }
    }

    var sprite: PixelCharacterSprite {
        switch self {
        case .dino: .dino
        case .ghost: .ghost
        case .crab: .crab
        case .duck: .duck
        case .claude: .claude
        case .cat: .cat
        case .robot: .robot
        case .octopus: .octopus
        case .frog: .frog
        case .slime: .slime
        }
    }
}
